// Compiles WGSL generated by maxwell2wgsl with Tint, the WGSL compiler of
// Chrome, via Dawn (npm package "webgpu"). Creates each shader module, the
// render pipelines of the render test and the compute pipelines, but submits no work: executing Dawn on
// Mesa's lavapipe aborted in the sandbox the spike was written in, while
// compilation and pipeline creation work. Pixels are checked by
// render_test.py (wgpu-native).
//
//   node tint_check.mjs <dir with the generated .wgsl files>
//
// Exit code 77 = skipped (package or GPU adapter missing; ctest SKIP).
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const SKIP = 77;
let webgpu;
try {
    // LGP_WEBGPU_DIR = the package directory (node_modules/webgpu) of an
    // install outside the repository, e.g. `npm install --prefix <dir> webgpu`.
    const dir = process.env.LGP_WEBGPU_DIR;
    webgpu = await import(dir ? pathToFileURL(path.join(dir, 'index.js')).href : 'webgpu');
} catch (e) {
    console.log(`SKIP: npm package "webgpu" not installed (${e.code ?? e.message})`);
    process.exit(SKIP);
}
Object.assign(globalThis, webgpu.globals);
// Keep the instance referenced: once garbage-collected, Dawn crashes in
// InstanceBase::ProcessEvents (seen as random aborts with more modules).
const gpu = webgpu.create([]);
globalThis.lgpGpuInstance = gpu;
const adapter = await gpu.requestAdapter();
if (!adapter) {
    console.log('SKIP: no WebGPU adapter (install a Vulkan driver, e.g. mesa-vulkan-drivers/lavapipe)');
    process.exit(SKIP);
}
const device = await adapter.requestDevice();
const dir = process.argv[2];
let failures = 0;

async function module(name) {
    const code = fs.readFileSync(path.join(dir, `${name}.wgsl`), 'utf8');
    device.pushErrorScope('validation');
    const m = device.createShaderModule({ code, label: name });
    const info = await m.getCompilationInfo();
    const err = await device.popErrorScope();
    for (const msg of info.messages) {
        console.log(`${name}:${msg.lineNum}:${msg.linePos}: ${msg.type}: ${msg.message}`);
        // Warnings count as failures too: generated code should be clean.
        failures++;
    }
    if (err) {
        console.log(`${name}: ${err.message}`);
        failures++;
    }
    return m;
}

async function pipeline(vsName, fsName, attributes) {
    const vs = await module(vsName), fsm = await module(fsName);
    let offset = 0;
    const attrs = attributes.map(([loc, comps]) => {
        const a = { shaderLocation: loc, offset, format: `float32x${comps}` };
        offset += comps * 4;
        return a;
    });
    device.pushErrorScope('validation');
    device.createRenderPipeline({
        layout: 'auto',
        vertex: { module: vs, entryPoint: 'main', buffers: [{ arrayStride: offset, attributes: attrs }] },
        fragment: { module: fsm, entryPoint: 'main', targets: [{ format: 'rgba32float' }] },
        primitive: { topology: 'triangle-list' },
    });
    const err = await device.popErrorScope();
    if (err) {
        console.log(`pipeline ${vsName} + ${fsName}: ${err.message}`);
        failures++;
    }
}

const isCompute = (f) => f.startsWith('cs_');
for (const f of fs.readdirSync(dir).filter((f) => f.endsWith('.wgsl') && !isCompute(f)).sort()) await module(f.slice(0, -5));
await pipeline('vs_transform.fs_textured', 'fs_textured', [[0, 4], [1, 4], [2, 2]]);
await pipeline('vs_transform.fs_alpha_loop', 'fs_alpha_loop', [[0, 4], [1, 4], [2, 2]]);
// Compute pipelines (workgroup size overrides, workgroup arrays, atomics).
for (const name of fs.readdirSync(dir).filter((f) => isCompute(f) && f.endsWith('.wgsl')).sort()) {
    const m = await module(name.slice(0, -5));
    device.pushErrorScope('validation');
    device.createComputePipeline({ layout: 'auto', compute: { module: m, entryPoint: 'main' } });
    const err = await device.popErrorScope();
    if (err) {
        console.log(`compute pipeline ${name}: ${err.message}`);
        failures++;
    }
}
console.log(failures ? `${failures} problem(s)` : 'tint check passed');
// Dawn's instance teardown is not needed here and was flaky on lavapipe.
process.exit(failures ? 1 : 0);
